function Sparkline({variant=0}: {variant?:number}) { const lines=['0,33 8,31 15,34 23,22 30,26 37,20 44,24 51,10 58,15 65,11 72,15 80,6 87,10 94,4 102,8 110,1','0,34 9,28 18,31 26,21 34,24 43,14 51,18 59,11 68,15 76,9 84,11 93,3 102,8 110,2','0,28 9,27 18,31 26,21 34,25 43,19 51,21 59,13 68,20 76,9 84,15 93,7 102,10 110,4','0,30 9,25 18,29 26,18 34,22 43,12 51,16 59,9 68,15 76,8 84,12 93,4 102,9 110,1'];return <svg className=\"sparkline\" viewBox=\"0 0 112 42\"><defs><linearGradient id={'fade'+variant} x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0%\" stopColor=\"#75bca5\" stopOpacity=\".24\"/><stop offset=\"100%\" stopColor=\"#75bca5\" stopOpacity=\"0\"/></linearGradient></defs><polygon points={"'`0,42 ${lines[variant]} 110,42`} fill={`url(#fade${variant})`}/><polyline points={lines[variant]} fill="none" stroke="#72b79c" strokeWidth="1.7"/></svg>}

export function App() {
