  function exportOrders(){const list=selected.length?orders.filter(o=>selected.includes(o.id)):filtered;const csv='"'\\uFEFF'+[['Заказ','Покупатель','Email','Дата','Сумма','Статус','Оплата'],...list.map(o=>[o.id,o.name,o.email,o.date,o.total,statuses[o.status].label,o.paid?'Оплачен':'Ожидает'])].map(r=>r.map(x=>'\"'+String(x).replaceAll('\"','\"\"')+'\"').join(';')).join('\\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));a.download='forma-orders.csv';a.click();URL.revokeObjectURL(a.href);notify("'`Экспортировано заказов: ${list.length}`)}
  function moveColumn(from:string,to:string){setColumns(cols=>{const next=cols.filter(c=>c!==from);next.splice(cols.indexOf(to),0,from);return next});setDragged(null)}
