let s=fs.readFileSync('index.html','utf8').replace('lang=\"en\"','lang=\"ru\"').replace('<title>Gravity UI eval</title>','<meta name=\"theme-color\" content=\"#26775a\" />\\n    <meta name=\"description\" content=\"Forma — управление заказами, покупателями и вашим магазином в одном месте.\" />\\n    <title>Forma — управление магазином</title>');
fs.writeFileSync('index.html',s);
s=fs.readFileSync('src/App.tsx','utf8').replace(\"[storeName,setStoreName]=useState('Forma Store')\", \"[storeName,setStoreName]=useState(()=>localStorage.getItem('forma-store')||'Forma Store'),[contactEmail,setContactEmail]=useState(()=>localStorage.getItem('forma-email')||'admin@forma.store'),[timezone,setTimezone]=useState(()=>localStorage.getItem('forma-timezone')||'moscow')\");
s=s.replace(\"setStoreName(String(data.get('store')));notify('Настройки сохранены')\", \"setStoreName(String(data.get('store')));setContactEmail(String(data.get('email')));setTimezone(String(data.get('timezone')));localStorage.setItem('forma-store',String(data.get('store')));localStorage.setItem('forma-email',String(data.get('email')));localStorage.setItem('forma-timezone',String(data.get('timezone')));notify('Настройки сохранены')\");
s=s.replace('defaultValue=\"admin@forma.store\"','defaultValue={contactEmail}').replace('<select defaultValue=\"moscow\">','<select name=\"timezone\" defaultValue={timezone}>');
fs.writeFileSync('src/App.tsx',s);
JS
npx --yes prettier --write src/App.tsx src/styles.css index.html"

